('product_blueprint_handoff.data_model.entity_catalogue', 1, '{"allowed_record_classes": "historical_synthetic, live, simulated", "constraints": "Exactly one edition is \"current\" at a time | starts_at > season_start; T−7 = starts_at − 7 days drives the cash gate | is_fictional = true for the 2025 assignment edition; such an edition can never be current", "derived": "False", "domain": "A Organisation and relationship management", "entity": "FESTIVAL_EDITION", "example_label": "synthetic 2025 record (assignment dataset; fictional)", "example_record": "{\"edition_id\": \"ED-2025\", \"name\": \"CampusFest 2025\", \"starts_at\": \"2025-04-12 10:00 IST\", \"is_fictional\": true, \"record_class\": \"historical_synthetic\"}", "primary_key": "edition_id", "provenance_note": "Edition-level; the 2025 row comes from stg.event with is_fictional = true", "purpose": "One edition of the festival; scopes targets, inventory, scenarios and every season record", "versioning": "mutable with audit"}'),
('product_blueprint_handoff.data_model.entity_catalogue', 2, '{"allowed_record_classes": "operating_plan", "brief_terms": "Categories", "constraints": "Names unique within a parent | Exclusivity is granted on a category node; narrow = a child node", "derived": "False", "domain": "A Organisation and relationship management", "entity": "CATEGORY", "example_label": "approved operating-plan record (D-010)", "example_record": "{\"category_id\": \"CAT-FIN\", \"name\": \"Consumer fintech\", \"tier\": \"T1\"}", "primary_key": "category_id", "provenance_note": "Reference data; changes versioned and approved", "purpose": "Sponsor category used for targeting, exclusivity and premium-asset limits (one premium asset per category)", "relationships": "parent_category_id → CATEGORY", "versioning": "mutable with audit"}'),
('product_blueprint_handoff.data_model.entity_catalogue', 3, '{"allowed_record_classes": "historical_synthetic, external_research, live, simulated", "brief_terms": "Sponsors", "constraints": "Normalised display_name unique per edition-independent registry (duplicate check before insert) | lifecycle_status = research_target until an INTERACTION with a named CONTACT exists (provenance rule 4) | past_sponsor set only from a CONTRACT in an earlier edition", "derived": "False", "domain": "A Organisation and relationship management", "entity": "SPONSOR", "example_label": "synthetic 2025 record (assignment dataset; fictional)", "example_record": "{\"sponsor_id\": \"A027\", \"display_name\": \"Cedar Pantry\", \"category (2025 industry)\": \"Consumer products\", \"lifecycle_status\": \"prospect\", \"record_class\": \"historical_synthetic\"}", "primary_key": "sponsor_id", "provenance_note": "Mixed classes in one registry: each row carries record_class; 2025 brands are historical_synthetic and never merge with live sponsors of the same name", "purpose": "An organisation that is, was or may become a sponsor (the 2025 \"brand\")", "relationships": "category_id → CATEGORY", "versioning": "mutable with audit"}'),
('product_blueprint_handoff.data_model.entity_catalogue', 4, '{"allowed_record_classes": "historical_synthetic, live, simulated", "brief_terms": "Contacts", "constraints": "A contact belongs to exactly one sponsor | decision_role defaults to unknown; the AI must not infer it from job_title | opted_out contacts cannot receive outreach (blocking rule on OUTREACH_ATTEMPT)", "derived": "False", "domain": "A Organisation and relationship management", "entity": "CONTACT", "example_label": "synthetic 2025 record (assignment dataset; fictional)", "example_record": "{\"contact_id\": \"SCON054\", \"sponsor_id\": \"A027\", \"full_name\": \"Zoya Gupta\", \"job_title\": \"Brand Marketing Lead\", \"decision_role\": \"unknown\"}", "primary_key": "contact_id", "provenance_note": "Personal data: restricted read; source of every contact detail recorded in source_ref", "purpose": "A person at a sponsor", "relationships": "sponsor_id → SPONSOR", "versioning": "mutable with audit"}'),
('product_blueprint_handoff.data_model.entity_catalogue', 5, '{"allowed_record_classes": "external_research", "brief_terms": "Prospects", "constraints": "Never counted in pipeline or forecast totals | route_class A (actual introduction) requires a linked REFERRAL with commitment_status = committed | A new assessment supersedes the old one (versioned)", "derived": "False", "domain": "A Organisation and relationship management", "entity": "PROSPECT_RESEARCH", "example_label": "external research record (real company or festival; research only)", "example_record": "{\"research_id\": \"PR-001\", \"sponsor\": \"Zerodha\", \"route_class\": \"V1\", \"action\": \"1 Pursue now\", \"attractiveness\": 94, \"accessibility\": 70}", "primary_key": "research_id", "provenance_note": "Always external_research; every score cites SRC-ids", "purpose": "Research assessment of a sponsor not yet in conversation (the W-001 prospect register)", "relationships": "sponsor_id → SPONSOR; edition_id → FESTIVAL_EDITION", "versioning": "full-state versions"}'),
('product_blueprint_handoff.data_model.entity_catalogue', 6, '{"allowed_record_classes": "live, simulated", "brief_terms": "Referrals", "constraints": "Recruited creators counted by recruited_at within the season (K-B4b-01)", "derived": "False", "domain": "A Organisation and relationship management", "entity": "NETWORK_PARTNER", "example_label": "illustrative live record (invented for this document; no such record exists)", "example_record": "{\"partner_id\": \"NP-014\", \"partner_type\": \"creator\", \"name\": \"(creator name)\", \"status\": \"active\"}", "primary_key": "partner_id", "provenance_note": "Live only; no 2025 equivalent beyond campaign names", "purpose": "A person or organisation that refers sponsors: creator, VC fund, alumnus, past sponsor", "relationships": "owner_member_id → TEAM_MEMBER", "versioning": "mutable with audit"}'),
('product_blueprint_handoff.data_model.entity_catalogue', 7, '{"allowed_record_classes": "live, simulated", "brief_terms": "Referrals", "constraints": "committed requires a named contact_id and an agreed meeting (D-010 definition) | Only committed referrals count toward the ≥ 6 introductions rule | A referral never implies an opportunity; the opportunity is created after qualification", "derived": "False", "domain": "A Organisation and relationship management", "entity": "REFERRAL", "example_label": "illustrative live record (invented for this document; no such record exists)", "example_record": "{\"referral_id\": \"RF-003\", \"partner_type\": \"vc_fund\", \"commitment_status\": \"speculative\", \"contact_id\": null}", "primary_key": "referral_id", "provenance_note": "Live only. D-010 records 0 committed introductions today; nothing may be back-filled without a source", "purpose": "An introduction or referral of a sponsor contact by a network partner (B3 introductions, B4b creator referrals, sponsor referrals)", "relationships": "partner_id → NETWORK_PARTNER; sponsor_id → SPONSOR; contact_id → CONTACT; campaign_id → CAMPAIGN", "versioning": "full-state versions"}'),
('product_blueprint_handoff.data_model.entity_catalogue', 8, '{"allowed_record_classes": "historical_synthetic, live, simulated", "brief_terms": "Relationship owners; Owners", "constraints": "Roles are assigned in ROLE_ASSIGNMENT, never stored here | Deactivated members keep their history", "derived": "False", "domain": "A Organisation and relationship management", "entity": "TEAM_MEMBER", "example_label": "synthetic 2025 record (assignment dataset; fictional)", "example_record": "{\"member_id\": \"T01\", \"full_name\": \"Riya Kapoor\", \"record_class\": \"historical_synthetic\"}", "primary_key": "member_id", "provenance_note": "2025 owners (T01, T02, T05) are historical_synthetic and are not user accounts", "purpose": "A festival team member: relationship owner, task owner, system user", "versioning": "mutable with audit"}'),
('product_blueprint_handoff.data_model.entity_catalogue', 9, '{"allowed_record_classes": "historical_synthetic, live, simulated", "brief_terms": "Relationship owners", "constraints": "At most one current owner per subject | A handoff closes the old assignment and opens a new one in the same transaction", "derived": "False", "domain": "A Organisation and relationship management", "entity": "OWNERSHIP_ASSIGNMENT", "example_label": "synthetic 2025 record (assignment dataset; fictional)", "example_record": "{\"subject\": \"opportunity O028\", \"member_id\": \"T01\", \"valid_from\": \"2025-03-09\"}", "primary_key": "assignment_id", "provenance_note": "Versioned so time-to-handoff and owner load can be measured", "purpose": "Who owns a sponsor relationship or opportunity over time (handoffs are the 2025 leak point)", "relationships": "member_id → TEAM_MEMBER", "versioning": "full-state versions"}'),
('product_blueprint_handoff.data_model.entity_catalogue', 10, '{"allowed_record_classes": "operating_plan", "brief_terms": "Channels", "constraints": "channel_group drives every channel KPI; changing it is a versioned decision", "derived": "False", "domain": "B Acquisition and campaign management", "entity": "CHANNEL", "example_label": "approved operating-plan record (D-010)", "example_record": "{\"channel_id\": \"CH-INTRO\", \"name\": \"introduction\", \"channel_group\": \"warm\"}", "primary_key": "channel_id", "provenance_note": "Reference data", "purpose": "Reference list of acquisition channels and their group (warm / inbound / cold / renewal / premium)", "versioning": "mutable with audit"}'),
('product_blueprint_handoff.data_model.entity_catalogue', 11, '{"allowed_record_classes": "historical_synthetic, live, simulated", "brief_terms": "Campaigns", "constraints": "A campaign on an inactive (cold-only) channel cannot be activated without a recorded decision | Every outreach attempt belongs to exactly one campaign", "derived": "False", "domain": "B Acquisition and campaign management", "entity": "CAMPAIGN", "example_label": "synthetic 2025 record (assignment dataset; fictional)", "example_record": "{\"campaign_id\": \"SC05\", \"name\": \"Creator Network Referrals\", \"channel\": \"introduction\", \"channel_group\": \"warm\"}", "primary_key": "campaign_id", "provenance_note": "2025 campaigns SC01–SC06 are historical_synthetic", "purpose": "A planned acquisition effort with a channel, owner, window and bet", "relationships": "edition_id → FESTIVAL_EDITION; channel_id → CHANNEL; bet_id → BET; owner_member_id → TEAM_MEMBER", "versioning": "mutable with audit"}'),
('product_blueprint_handoff.data_model.entity_catalogue', 12, '{"allowed_record_classes": "historical_synthetic, live, simulated", "brief_terms": "Outreach attempts", "constraints": "Blocked if contact opted out | Derived flags (delivered, replied, meeting booked/held) are computed from INTERACTION, not stored", "derived": "False", "domain": "B Acquisition and campaign management", "entity": "OUTREACH_ATTEMPT", "example_label": "synthetic 2025 record (assignment dataset; fictional)", "example_record": "{\"attempt_id\": \"SA0037\", \"sponsor_id\": \"A027\", \"campaign_id\": \"SC03\", \"root_event_type\": \"outreach_sent\"}", "primary_key": "attempt_id", "provenance_note": "Attempts ≠ contacts ≠ sponsors: grain stated with every rate", "purpose": "One root touch to a contact (outreach sent, introduction received, inbound form) and its follow-on events", "relationships": "campaign_id → CAMPAIGN; sponsor_id → SPONSOR; contact_id → CONTACT; referral_id → REFERRAL; owner_member_id → TEAM_MEMBER", "versioning": "append-only"}'),
('product_blueprint_handoff.data_model.entity_catalogue', 13, '{"allowed_record_classes": "historical_synthetic, live, simulated", "brief_terms": "Interactions", "constraints": "Append-only; corrections are new events | Exact duplicates rejected on (attempt_id, event_type, occurred_at) | Events at or after festival start excluded from pre-fest metrics", "derived": "False", "domain": "B Acquisition and campaign management", "entity": "INTERACTION", "example_label": "synthetic 2025 record (assignment dataset; fictional)", "example_record": "{\"interaction_id\": \"SI00133\", \"attempt_id\": \"SA0037\", \"event_type\": \"outreach_sent\", \"occurred_at\": \"2025-03-03 10:00 IST\"}", "primary_key": "interaction_id", "provenance_note": "Import retries detected by the duplicate rule (2025 had 3)", "purpose": "An event in an attempt: delivered, replied, meeting booked or held, opted out, note", "relationships": "attempt_id → OUTREACH_ATTEMPT; origin_interaction_id → INTERACTION; logged_by → TEAM_MEMBER", "versioning": "append-only"}'),
('product_blueprint_handoff.data_model.entity_catalogue', 14, '{"allowed_record_classes": "historical_synthetic, live, simulated", "brief_terms": "Meetings", "constraints": "held requires scheduled_at ≤ now | A renewal screening call is a MEETING with purpose renewal_screen (K-B4a-01)", "derived": "False", "domain": "B Acquisition and campaign management", "entity": "MEETING", "example_label": "synthetic 2025 record (assignment dataset; fictional)", "example_record": "{\"meeting_id\": \"from SI00003\", \"sponsor_id\": \"A001\", \"status\": \"booked\", \"scheduled_at\": \"2025-03-05 14:00 IST\"}", "primary_key": "meeting_id", "provenance_note": "2025 meetings are derived from meeting_booked / meeting_held interactions", "purpose": "A scheduled or held meeting with a sponsor (in 2025 only an event type; a first-class record live)", "relationships": "attempt_id → OUTREACH_ATTEMPT; opportunity_id → OPPORTUNITY; sponsor_id → SPONSOR", "versioning": "mutable with audit"}'),
('product_blueprint_handoff.data_model.entity_catalogue', 15, '{"allowed_record_classes": "historical_synthetic, live, simulated", "brief_terms": "Qualification", "constraints": "Latest version on or before D applies; never sum versions | qualified starts the B1 SLA clock (deal ≤ 5 days, proposal ≤ 10 days)", "derived": "False", "domain": "B Acquisition and campaign management", "entity": "QUALIFICATION_VERSION", "example_label": "synthetic 2025 record (assignment dataset; fictional)", "example_record": "{\"history_id\": \"BQ0081\", \"sponsor_id\": \"A027\", \"status\": \"qualified\", \"valid_from\": \"2025-03-04 12:00 IST\"}", "primary_key": "history_id", "provenance_note": "Full-state versions as in 2025", "purpose": "Full-state qualification status of a sponsor (unreviewed, engaged, qualified, unqualified, dormant)", "relationships": "sponsor_id → SPONSOR; edition_id → FESTIVAL_EDITION; source_campaign_id → CAMPAIGN", "versioning": "full-state versions"}'),
('product_blueprint_handoff.data_model.entity_catalogue', 16, '{"allowed_record_classes": "historical_synthetic, live, simulated", "brief_terms": "Opportunities", "constraints": "Sponsor must not be research_target (needs a recorded interaction) | originating_campaign_id immutable | Stage and values live in OPPORTUNITY_STAGE_VERSION only", "derived": "False", "domain": "B Acquisition and campaign management", "entity": "OPPORTUNITY", "example_label": "synthetic 2025 record (assignment dataset; fictional)", "example_record": "{\"opportunity_id\": \"O028\", \"sponsor_id\": \"A027\", \"originating_campaign_id\": \"SC03\", \"support_type\": \"cash\"}", "primary_key": "opportunity_id", "provenance_note": "Live opportunities never mix with 2025 rows in pipeline totals", "purpose": "One potential partnership with one sponsor in one edition", "relationships": "sponsor_id → SPONSOR; edition_id → FESTIVAL_EDITION; primary_contact_id → CONTACT; originating_campaign_id → CAMPAIGN; bet_id → BET", "versioning": "mutable with audit"}'),
('product_blueprint_handoff.data_model.entity_catalogue', 17, '{"allowed_record_classes": "historical_synthetic, live, simulated", "brief_terms": "Deal status", "constraints": "Append-only full-state versions | confirmed_value > 0 only when stage = partner_confirmed and a CONTRACT exists (live) | lost / withdrawn require drop_reason | confirmed_value is signed value, never cash", "derived": "False", "domain": "B Acquisition and campaign management", "entity": "OPPORTUNITY_STAGE_VERSION", "example_label": "synthetic 2025 record (assignment dataset; fictional)", "example_record": "{\"history_id\": \"OH00138\", \"opportunity_id\": \"O028\", \"stage\": \"negotiating\", \"proposed_value\": 110000, \"confirmed_value\": 0}", "primary_key": "history_id", "provenance_note": "2025 versions are historical_synthetic", "purpose": "Full-state deal status with proposed and confirmed value (the deal status history)", "relationships": "opportunity_id → OPPORTUNITY; owner_member_id → TEAM_MEMBER", "versioning": "full-state versions"}'),
