('product_blueprint_handoff.data_model.entity_catalogue', 19, '{"allowed_record_classes": "live, simulated", "brief_terms": "Slot availability", "constraints": "(asset_id, slot_no) unique | sold requires a contract line; one line per slot | Holds expire automatically; a held slot cannot be held twice (row lock)", "derived": "False", "domain": "C Sponsorship commercial management", "entity": "ASSET_SLOT", "example_label": "illustrative live record (invented for this document; no such record exists)", "example_record": "{\"slot_id\": \"INV-ACT-07\", \"asset\": \"activation\", \"status\": \"held\", \"hold_expires_at\": \"(date)\"}", "primary_key": "slot_id", "provenance_note": "Live; status history in AUDIT_EVENT", "purpose": "One sellable unit of an asset and its availability", "relationships": "asset_id → INVENTORY_ASSET; held_for_opportunity_id → OPPORTUNITY; sold_contract_line_id → CONTRACT_LINE", "versioning": "mutable with audit"}'),
('product_blueprint_handoff.data_model.entity_catalogue', 20, '{"allowed_record_classes": "operating_plan", "brief_terms": "Pricing", "constraints": "Effective versions do not overlap per asset | Discount below floor needs an approval recorded in AUDIT_EVENT", "derived": "False", "domain": "C Sponsorship commercial management", "entity": "PRICE_LIST_ENTRY", "example_label": "model record (frozen v4.1) as plan", "example_record": "{\"asset\": \"presenting\", \"realised_low\": \"₹1.0L\", \"realised_mode\": \"₹1.6L\", \"realised_high\": \"₹2.6L\", \"advance_share\": 0.5}", "primary_key": "price_id", "provenance_note": "Prices are assumptions on asking-price ratios, labelled A", "purpose": "Versioned rate card: list price, floor and realised range per asset", "relationships": "asset_id → INVENTORY_ASSET; assumption_id → MODEL_ASSUMPTION", "versioning": "full-state versions"}'),
