('product_blueprint_handoff.data_model.entity_catalogue', 23, '{"allowed_record_classes": "live, simulated", "brief_terms": "Proposals", "constraints": "sent_at sets the opportunity stage to proposal_sent | An AI may draft (L4) but only a human sends", "derived": "False", "domain": "C Sponsorship commercial management", "entity": "PROPOSAL", "example_label": "illustrative live record (invented for this document; no such record exists)", "example_record": "{\"proposal_id\": \"PRP-0102\", \"opportunity\": \"(live)\", \"proposed_value\": \"₹1.6L\", \"status\": \"sent\"}", "primary_key": "proposal_id", "provenance_note": "Live; drafts by AI carry ai_action_id", "purpose": "A versioned offer sent to a sponsor", "relationships": "opportunity_id → OPPORTUNITY; package_id → PACKAGE", "versioning": "full-state versions"}'),
('product_blueprint_handoff.data_model.entity_catalogue', 24, '{"allowed_record_classes": "live, simulated", "brief_terms": "Contracts; Signed values", "constraints": "signed_value_total = SUM(CONTRACT_LINE.value) | Exactly one active contract per confirmed opportunity | Amendments are new versions", "derived": "False", "domain": "C Sponsorship commercial management", "entity": "CONTRACT", "example_label": "illustrative live record (invented for this document; no such record exists)", "example_record": "{\"contract_id\": \"CT-0021\", \"signed_value_total\": \"₹1.20L\", \"payment_terms\": \"50/50\"}", "primary_key": "contract_id", "provenance_note": "Live only; 2025 signed values exist only as stage versions (no contracts)", "purpose": "The signed sponsorship agreement", "relationships": "opportunity_id → OPPORTUNITY; signatory_contact_id → CONTACT", "versioning": "full-state versions"}'),
('product_blueprint_handoff.data_model.entity_catalogue', 25, '{"allowed_record_classes": "live, simulated", "brief_terms": "Signed values", "constraints": "value > 0 | Cash KPIs use consideration_type = cash lines only | in_kind lines must have an IN_KIND_CONTRIBUTION", "derived": "False", "domain": "C Sponsorship commercial management", "entity": "CONTRACT_LINE", "example_label": "illustrative live record (invented for this document; no such record exists)", "example_record": "{\"contract_line_id\": \"CL-0021-1\", \"consideration_type\": \"cash\", \"value\": \"₹1.20L\"}", "primary_key": "contract_line_id", "provenance_note": "Live only", "purpose": "A component of a contract: an asset sold, with its value and consideration type (cash or in-kind)", "relationships": "contract_id → CONTRACT; asset_id → INVENTORY_ASSET; price_id → PRICE_LIST_ENTRY", "versioning": "mutable with audit"}'),
('product_blueprint_handoff.data_model.entity_catalogue', 26, '{"allowed_record_classes": "live, simulated", "brief_terms": "Exclusivity", "constraints": "No overlapping active grants for the same category node or its ancestors | Must attach to a contract with a title or presenting line (no standalone exclusives) | Scope recorded for K-B5-06", "derived": "False", "domain": "C Sponsorship commercial management", "entity": "EXCLUSIVITY_GRANT", "example_label": "illustrative live record (invented for this document; no such record exists)", "example_record": "{\"grant_id\": \"EX-001\", \"category\": \"payments (child of fintech)\", \"scope\": \"narrow\"}", "primary_key": "grant_id", "provenance_note": "Live only", "purpose": "Category exclusivity granted inside a premium contract", "relationships": "contract_id → CONTRACT; category_id → CATEGORY", "versioning": "mutable with audit"}'),
('product_blueprint_handoff.data_model.entity_catalogue', 27, '{"allowed_record_classes": "historical_synthetic, live, simulated", "constraints": "Association only, never causal uplift", "derived": "False", "domain": "C Sponsorship commercial management", "entity": "CONTRACT_DELIVERABLE", "example_label": "synthetic 2025 record (assignment dataset; fictional)", "example_record": "{\"deliverable_id\": \"L001\", \"opportunity_id\": \"O001\", \"attendee_campaign_ref\": \"C03 Creator Partners\"}", "primary_key": "deliverable_id", "provenance_note": "2025 activation links are historical_synthetic", "purpose": "What the festival owes the sponsor (logo, booth, activation, posts) and proof of delivery (the 2025 activation links)", "relationships": "contract_line_id → CONTRACT_LINE; opportunity_id → OPPORTUNITY", "versioning": "mutable with audit"}'),
('product_blueprint_handoff.data_model.entity_catalogue', 28, '{"allowed_record_classes": "live, simulated", "brief_terms": "Payment schedules; Advance due", "constraints": "SUM(amount_due) over a contract = cash lines total | Cash lines only | status derived from allocations, not typed", "derived": "False", "domain": "D Financial management", "entity": "PAYMENT_SCHEDULE_ITEM", "example_label": "illustrative live record (invented for this document; no such record exists)", "example_record": "{\"kind\": \"advance\", \"amount_due\": \"₹0.60L\", \"due_date\": \"signing + 7 days\"}", "primary_key": "schedule_item_id", "provenance_note": "Live only", "purpose": "An instalment owed under a contract (advance, balance), with due date", "relationships": "contract_id → CONTRACT", "versioning": "mutable with audit"}'),
('product_blueprint_handoff.data_model.entity_catalogue', 29, '{"allowed_record_classes": "live, simulated", "brief_terms": "Invoices", "constraints": "Issued invoices are never edited; cancel with a credit note | Only finance role issues (AI may draft at L4)", "derived": "False", "domain": "D Financial management", "entity": "INVOICE", "example_label": "illustrative live record (invented for this document; no such record exists)", "example_record": "{\"invoice_no\": \"INV/2026/014\", \"amount\": \"₹0.60L\", \"issued_at\": \"signing day\"}", "primary_key": "invoice_id", "provenance_note": "Live only; restricted (financial)", "purpose": "A tax invoice issued to a sponsor", "relationships": "contract_id → CONTRACT; schedule_item_id → PAYMENT_SCHEDULE_ITEM", "versioning": "immutable"}'),
('product_blueprint_handoff.data_model.entity_catalogue', 30, '{"allowed_record_classes": "live, simulated", "brief_terms": "Receipts", "constraints": "amount > 0 | record_class ∈ {live, simulated}: no receipt can be historical, researched or modelled | Written by finance role only; never by the AI (forbidden action) | Counted as collected only when reconciled", "derived": "False", "domain": "D Financial management", "entity": "RECEIPT", "example_label": "illustrative live record (invented for this document; no such record exists)", "example_record": "{\"receipt_id\": \"RC-0009\", \"amount\": \"₹0.60L\", \"method\": \"bank transfer\", \"reconciled\": true}", "primary_key": "receipt_id", "provenance_note": "Restricted; every edit audited", "purpose": "Money actually received; the only source of \"cash collected\"", "relationships": "sponsor_id → SPONSOR; recorded_by → TEAM_MEMBER", "versioning": "immutable"}'),
