('product_blueprint_handoff.data_model.entity_catalogue', 33, '{"allowed_record_classes": "live, simulated", "brief_terms": "In-kind contributions", "constraints": "Never counted in cash KPIs | consideration_type of the line must be in_kind", "derived": "False", "domain": "D Financial management", "entity": "IN_KIND_CONTRIBUTION", "example_label": "illustrative live record (invented for this document; no such record exists) (modelled on 2025 in-kind deal O005)", "example_record": "{\"description\": \"(beverage supply)\", \"declared_value\": \"₹1.0L\", \"status\": \"promised\"}", "primary_key": "in_kind_id", "provenance_note": "2025 in-kind deals exist only as support_type = in_kind", "purpose": "Goods or services given instead of cash; tracked and valued separately", "relationships": "contract_line_id → CONTRACT_LINE", "versioning": "mutable with audit"}'),
('product_blueprint_handoff.data_model.entity_catalogue', 34, '{"allowed_record_classes": "live, simulated", "constraints": "No cash budget exists today [U]; the cap is an open decision", "derived": "False", "domain": "D Financial management", "entity": "EXPENSE", "example_label": "illustrative live record (invented for this document; no such record exists)", "example_record": "{\"bet\": \"B5\", \"amount\": \"(printing)\"}", "primary_key": "expense_id", "provenance_note": "Live only", "purpose": "Money spent on acquisition (spend cap, K-C-04)", "relationships": "edition_id → FESTIVAL_EDITION; bet_id → BET; approved_by → TEAM_MEMBER", "versioning": "mutable with audit"}'),
