('product_blueprint_handoff.data_model.entity_catalogue', 36, '{"allowed_record_classes": "live, simulated", "brief_terms": "Dependencies", "constraints": "No cycles | No self-dependency", "derived": "False", "domain": "E Execution management", "entity": "TASK_DEPENDENCY", "example_label": "illustrative live record (invented for this document; no such record exists)", "example_record": "{\"task\": \"Send title proposal\", \"depends_on\": \"Confirm act booking\"}", "primary_key": "dependency_id", "provenance_note": "Live only", "purpose": "Task B cannot start until task A is done", "relationships": "task_id → TASK; depends_on_task_id → TASK", "versioning": "mutable with audit"}'),
