('product_blueprint_handoff.data_model.entity_catalogue', 41, '{"allowed_record_classes": "operating_plan", "brief_terms": "KPI definitions", "constraints": "Every KPI resolves to one metric definition", "derived": "False", "domain": "F Analytics and experimentation", "entity": "KPI_DEFINITION", "example_label": "approved operating-plan record (D-010)", "example_record": "{\"kpi_id\": \"K-B1-02\", \"name\": \"Qualified → proposal within 10 days\", \"bet\": \"B1\"}", "primary_key": "kpi_id", "provenance_note": "Plan record, versioned", "purpose": "Business definition of a KPI (kpi_dictionary.csv)", "relationships": "bet_id → BET; metric_id → METRIC_DEFINITION", "versioning": "full-state versions"}'),
