('product_blueprint_handoff.data_model.entity_catalogue', 44, '{"allowed_record_classes": "operating_plan", "constraints": "Immutable once effective (cannot change after results are seen)", "derived": "False", "domain": "F Analytics and experimentation", "entity": "THRESHOLD_RULE", "example_label": "approved operating-plan record (D-010)", "example_record": "{\"rule_id\": \"EX-B1a\", \"escalate_if\": \"proposal ≤ 10 days < 63% at W4\", \"response\": \"escalate to coordination lead\"}", "primary_key": "rule_id", "provenance_note": "Plan record", "purpose": "Versioned decision rule: trigger, response, owner role (D-010 operating thresholds)", "relationships": "kpi_id → KPI_DEFINITION; decision_id → DECISION_RECORD", "versioning": "full-state versions"}'),
