('strategy.resource_allocation.readme', 1, '{"Resource allocation: approved D-010 plan (stretch 60 window + 10 pre-season person-weeks)": "Status: approved D-010 effort accounting. Values in blue are inputs copied from the frozen D-010 outputs [C]; black cells are formulas; green cells link to another sheet."}'),
('strategy.resource_allocation.readme', 2, '{"Resource allocation: approved D-010 plan (stretch 60 window + 10 pre-season person-weeks)": "Sources: 05_STRATEGY/D010_approved/out/S9_stretch_effort_buildup.csv, S3_effort_stretch.csv, S7_ranking.csv, S8_cold_saving_by_scenario.csv, S1_shapley_by_scenario.csv."}'),
('strategy.resource_allocation.readme', 3, '{"Resource allocation: approved D-010 plan (stretch 60 window + 10 pre-season person-weeks)": "1 person-week (pw) = 40 h in-window; 36 usable h pre-season (4 h coordination). Nominal = at model hour rates; modelled = includes the lognormal hours multiplier and pre-season spill."}'),
('strategy.resource_allocation.readme', 4, '{"Resource allocation: approved D-010 plan (stretch 60 window + 10 pre-season person-weeks)": "Roles are D-010 operating roles [T]. Staffing (60 window pw = 6 FTE x 10 weeks; 10 pre-season pw = 2 people x 5 weeks) is a stated assumption [A] accepted in D-010."}'),
('strategy.resource_allocation.readme', 5, '{"Resource allocation: approved D-010 plan (stretch 60 window + 10 pre-season person-weeks)": "No cash budget exists in the data or the model [U]: creator incentives, deck design and sampling stock are unmodelled and must be capped separately."}'),
('strategy.resource_allocation.readme', 6, '{"Resource allocation: approved D-010 plan (stretch 60 window + 10 pre-season person-weeks)": "Do not edit the blue inputs to plan a different scenario: they are frozen model outputs. Use the Staffing sheet only to see the implications of a staffing assumption."}'),
