('data_foundation.original_sources.sponsor_dataset.read_me', 1, '{"description": "SPONSOR ACQUISITION DATA", "topic": "Context"}'),
('data_foundation.original_sources.sponsor_dataset.read_me', 2, '{"description": "CampusFest 2025 is a fictional two-day event on 12–13 April 2025. Records cover 15 January–20 April 2025. Brands, contacts and outreach are synthetic. Beardo is an illustrative case label, not a claim about a real business.", "topic": "Source guidance"}'),
('data_foundation.original_sources.sponsor_dataset.read_me', 3, '{"description": "Build around useful sponsor acquisition questions. Source records describe the target brands, their contacts, acquisition campaigns, outreach and responses, qualification changes, opportunities and partner activations. Choose your own metrics and interface. Partnership outcomes provide downstream context for marketing activity.", "topic": "Source guidance"}'),
('data_foundation.original_sources.sponsor_dataset.read_me', 4, '{"description": "Names appear first; stable IDs at the right distinguish entities and support joins. Multiple contacts or opportunities can belong to the same brand. Outreach attempts, contacts, responding brands, qualified brands and confirmed partnerships are different populations. Repeated outreach is not a new brand.", "topic": "Source guidance"}'),
('data_foundation.original_sources.sponsor_dataset.read_me', 5, '{"description": "Each selected date means the end of that day in Asia/Kolkata. All source timestamps include +05:30. Histories contain full-state versions: choose the latest eligible version per entity. Read planned dates as plans and completed interactions as actuals. A later response or partner outcome must not leak into earlier snapshots.", "topic": "Source guidance"}'),
('data_foundation.original_sources.sponsor_dataset.read_me', 6, '{"description": "Some exact source rows repeat with the same stable interaction/history ID after an import retry. Deduplicate identical source IDs. Distinct real attempts can still concern one contact or brand. Qualification and opportunity stage are different business records. Campaign association is observational, and a positive reply alone does not establish qualification or a confirmed partnership.", "topic": "Source guidance"}'),
('data_foundation.original_sources.sponsor_dataset.read_me', 7, '{"description": "Partner activations link confirmed sponsorship opportunities to named attendee acquisition campaigns. A planned activation does not establish causal uplift. Any partnership value is a simple reported amount in INR and is not proof of bank receipt.", "topic": "Source guidance"}'),
('data_foundation.original_sources.sponsor_dataset.read_me', 8, '{"description": "The Google Sheet contains typed dates and materialized source values. The CSV copy uses unambiguous ISO date text. The source pack contains no formulas or private reviewer answers.", "topic": "Source guidance"}'),
('data_foundation.original_sources.sponsor_dataset.field_guide', 1, '{"data_type": "text", "field": "event_name", "meaning": "Fictional event display name.", "source_table": "event.csv"}'),
